begin;
-- No legal text, percentage, approval, or production agreement is seeded.
create table public.contract_policy_versions_v1(
 id uuid primary key default extensions.gen_random_uuid(),kind text not null check(kind in('TEMPLATE','COMMISSION')),code text not null check(code~'^[A-Z][A-Z0-9_-]{2,79}$'),version integer not null check(version>0),
 library_id uuid not null references public.catalog_libraries(id),service_id uuid references public.catalog_services(id),currency text check(currency is null or currency~'^[A-Z]{3}$'),
 country_code text not null check(country_code~'^[A-Z]{2}$'),title_fr text not null check(length(btrim(title_fr))between 3 and 240),title_ar text not null check(length(btrim(title_ar))between 3 and 240),data jsonb not null check(jsonb_typeof(data)='object'),
 valid_from date not null,valid_until date,approval_reference text not null check(length(btrim(approval_reference))between 8 and 500),
 source_clause_set_version_id uuid references public.contract_clause_set_versions(id),supersedes_policy_version_id uuid references public.contract_policy_versions_v1(id),
 created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),content_hash text not null check(content_hash~'^[a-f0-9]{64}$'),unique(kind,code,version),
 check(valid_until is null or valid_until>valid_from),check(kind<>'COMMISSION'or(service_id is not null and currency is not null)),check(kind<>'TEMPLATE'or currency is null));
create table public.contract_policy_decisions_v1(policy_version_id uuid primary key references public.contract_policy_versions_v1(id),decision text not null check(decision in('APPROVE','REJECT')),content_hash text not null check(content_hash~'^[a-f0-9]{64}$'),reason text not null check(length(btrim(reason))between 10 and 2000),decided_by uuid not null references auth.users(id),decided_at timestamptz not null default clock_timestamp());
create table public.selected_quote_contract_drafts_v1(quote_version_id uuid primary key references public.quote_versions(id),request_id uuid not null references public.service_requests(id),request_version_id uuid not null references public.service_request_versions(id),selection_decision_rfq_id uuid not null references public.quote_selection_decisions(rfq_id),contract_id uuid not null unique references public.contracts(id),contract_version_id uuid not null unique references public.contract_versions(id),template_policy_version_id uuid not null references public.contract_policy_versions_v1(id),commission_policy_version_id uuid not null references public.contract_policy_versions_v1(id),source_hash text not null check(source_hash~'^[a-f0-9]{64}$'),created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp());
do $$declare t text;begin foreach t in array array['contract_policy_versions_v1','contract_policy_decisions_v1','selected_quote_contract_drafts_v1']loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);execute format('grant select on public.%I to authenticated',t);execute format('create trigger %I before update or delete on public.%I for each row execute function private.prevent_update_delete()',t||'_immutable',t);end loop;end$$;
create policy contract_policy_versions_staff_read on public.contract_policy_versions_v1 for select to authenticated using(private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','COMPLIANCE_MANAGER','FINANCE_MANAGER','READ_ONLY_AUDITOR']));
create policy contract_policy_decisions_staff_read on public.contract_policy_decisions_v1 for select to authenticated using(private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','COMPLIANCE_MANAGER','FINANCE_MANAGER','READ_ONLY_AUDITOR']));
create policy selected_quote_contract_drafts_party_read on public.selected_quote_contract_drafts_v1 for select to authenticated using(private.contract_party_access(contract_id));
create function private.contract_policy_manage_access_v1(p_kind text)returns boolean language sql stable security definer set search_path=pg_catalog,private as $$select auth.uid()is not null and auth.jwt()->>'aal'='aal2'and case p_kind when'TEMPLATE'then private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','COMPLIANCE_MANAGER'])when'COMMISSION'then private.has_platform_role(array['SUPER_ADMIN','FINANCE_MANAGER'])else false end$$;
revoke all on function private.contract_policy_manage_access_v1(text)from public,anon,authenticated,service_role;
create function private.contract_policy_applicable_v1(p_id uuid,p_library_id uuid,p_service_id uuid,p_currency text,p_as_of date,p_country_code text)returns boolean language sql stable security definer set search_path=pg_catalog,public as $$
 select exists(select 1 from public.contract_policy_versions_v1 p join public.contract_policy_decisions_v1 d on d.policy_version_id=p.id and d.decision='APPROVE'and d.content_hash=p.content_hash and d.decided_by<>p.created_by where p.id=p_id and p.library_id=p_library_id and p.country_code=p_country_code and(p.service_id is null or p.service_id=p_service_id)and(p.kind='TEMPLATE'or p.currency=p_currency)and p.valid_from<=p_as_of and(p.valid_until is null or p.valid_until>p_as_of)and not exists(select 1 from public.contract_policy_versions_v1 successor join public.contract_policy_decisions_v1 approved on approved.policy_version_id=successor.id and approved.decision='APPROVE'where successor.supersedes_policy_version_id=p.id and successor.valid_from<=p_as_of))
$$;
revoke all on function private.contract_policy_applicable_v1(uuid,uuid,uuid,text,date,text)from public,anon,authenticated,service_role;
create function public.create_contract_policy_version_v1(p_payload jsonb,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$
declare actor uuid:=auth.uid();policy_kind text:=p_payload->>'kind';library_id_value uuid;service_id_value uuid;source_id uuid;supersedes_id uuid;data_value jsonb;clauses_value jsonb;h text;cached jsonb;result jsonb;policy_id uuid;v integer;
begin
 if not private.contract_policy_manage_access_v1(policy_kind)then raise exception'CONTRACT_POLICY_MANAGEMENT_DENIED'using errcode='42501';end if;
 if p_payload is null or jsonb_typeof(p_payload)<>'object'or(p_payload-array['kind','code','version','library_id','service_id','currency','country_code','title_fr','title_ar','clauses','basis_points','basis_code','valid_from','valid_until','approval_reference','source_clause_set_version_id','supersedes_policy_version_id'])<>'{}'::jsonb or coalesce(p_payload->>'version','')!~'^[1-9][0-9]{0,8}$'then raise exception'INVALID_CONTRACT_POLICY'using errcode='22023';end if;
 library_id_value:=nullif(p_payload->>'library_id','')::uuid;service_id_value:=nullif(p_payload->>'service_id','')::uuid;source_id:=nullif(p_payload->>'source_clause_set_version_id','')::uuid;supersedes_id:=nullif(p_payload->>'supersedes_policy_version_id','')::uuid;v:=(p_payload->>'version')::integer;
 if coalesce(p_payload->>'country_code','')!~'^[A-Z]{2}$'or library_id_value is null or(service_id_value is not null and not exists(select 1 from public.catalog_services where id=service_id_value and library_id=library_id_value))then raise exception'CONTRACT_POLICY_CATALOG_SCOPE_MISMATCH'using errcode='23514';end if;
 if policy_kind='TEMPLATE'then
  if nullif(p_payload->>'currency','')is not null or p_payload?'basis_points'or p_payload?'basis_code'then raise exception'INVALID_CONTRACT_POLICY_FIELDS'using errcode='22023';end if;
  clauses_value:=p_payload->'clauses';
  if source_id is not null then
   select clauses into data_value from public.contract_clause_set_versions where id=source_id;
   if data_value is null or(clauses_value is not null and data_value<>clauses_value)then raise exception'CONTRACT_POLICY_SOURCE_CLAUSES_MISMATCH'using errcode='23514';end if;clauses_value:=data_value;
  end if;
  if jsonb_typeof(clauses_value)is distinct from'object'or length(btrim(coalesce(clauses_value->>'fr','')))not between 10 and 100000 or length(btrim(coalesce(clauses_value->>'ar','')))not between 10 and 100000 then raise exception'BILINGUAL_CONTRACT_CLAUSES_REQUIRED'using errcode='22023';end if;
  data_value:=jsonb_build_object('clauses',clauses_value);
 else
  if p_payload?'clauses'or source_id is not null then raise exception'INVALID_CONTRACT_POLICY_FIELDS'using errcode='22023';end if;
  if service_id_value is null or coalesce(p_payload->>'currency','')!~'^[A-Z]{3}$'or coalesce(p_payload->>'basis_points','')!~'^[0-9]{1,5}$'or(p_payload->>'basis_points')::integer not between 0 and 10000 or p_payload->>'basis_code'is distinct from'CONFIRMED_CLIENT_RECEIPT_AMOUNT'then raise exception'INVALID_COMMISSION_POLICY'using errcode='22023';end if;
  data_value:=jsonb_build_object('commission_basis_points',(p_payload->>'basis_points')::integer,'basis_code','CONFIRMED_CLIENT_RECEIPT_AMOUNT');
 end if;
 if supersedes_id is not null and not exists(select 1 from public.contract_policy_versions_v1 p where p.id=supersedes_id and p.kind=policy_kind and p.code=p_payload->>'code'and p.library_id=library_id_value and p.service_id is not distinct from service_id_value and p.currency is not distinct from nullif(p_payload->>'currency','')and p.country_code=p_payload->>'country_code'and p.version<v and p.valid_from<=(p_payload->>'valid_from')::date)then raise exception'CONTRACT_POLICY_SUPERSESSION_SCOPE_MISMATCH'using errcode='23514';end if;
 h:=private.canonical_request_hash(p_payload);cached:=private.begin_admin_command('contract.policy.create',p_idempotency_key,h,actor);if cached is not null then return cached;end if;
 insert into public.contract_policy_versions_v1(kind,code,version,library_id,service_id,currency,country_code,title_fr,title_ar,data,valid_from,valid_until,approval_reference,source_clause_set_version_id,supersedes_policy_version_id,created_by,content_hash)values(policy_kind,p_payload->>'code',v,library_id_value,service_id_value,case when policy_kind='COMMISSION'then p_payload->>'currency'end,p_payload->>'country_code',p_payload->>'title_fr',p_payload->>'title_ar',data_value,(p_payload->>'valid_from')::date,nullif(p_payload->>'valid_until','')::date,p_payload->>'approval_reference',source_id,supersedes_id,actor,h)returning id into policy_id;
 result:=jsonb_build_object('outcome','CONTRACT_POLICY_VERSION_PROPOSED','policy_version_id',policy_id,'content_hash',h,'status','PENDING_APPROVAL');
 insert into public.audit_events(actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(actor,'USER','contract.policy.proposed','contract_policy_version',policy_id::text,p_correlation_id,jsonb_build_object('kind',policy_kind,'content_hash',h),repeat('0',64));
 perform private.finish_admin_command('contract.policy.create',p_idempotency_key,actor,result);return result;
end$$;
revoke all on function public.create_contract_policy_version_v1(jsonb,text,uuid)from public,anon,authenticated,service_role;
grant execute on function public.create_contract_policy_version_v1(jsonb,text,uuid)to authenticated;
create function public.decide_contract_policy_version_v1(p_policy_version_id uuid,p_approve boolean,p_reason text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$
declare p public.contract_policy_versions_v1%rowtype;actor uuid:=auth.uid();h text;cached jsonb;result jsonb;
begin
 select*into p from public.contract_policy_versions_v1 where id=p_policy_version_id;
 if p.id is null or not private.contract_policy_manage_access_v1(p.kind)or p.created_by=actor then raise exception'CONTRACT_POLICY_INDEPENDENT_APPROVER_REQUIRED'using errcode='42501';end if;
 if p_approve is null or length(btrim(coalesce(p_reason,'')))not between 10 and 2000 then raise exception'INVALID_CONTRACT_POLICY_DECISION'using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('contract-commission:'||coalesce(p.service_id::text,p.library_id::text)||':'||coalesce(p.currency,p.kind),0));
 h:=private.canonical_request_hash(jsonb_build_object('policy_id',p.id,'content_hash',p.content_hash,'approve',p_approve,'reason',btrim(p_reason)));cached:=private.begin_admin_command('contract.policy.decide.'||p.id::text,p_idempotency_key,h,actor);if cached is not null then return cached;end if;
 if p_approve and p.kind='COMMISSION'and exists(select 1 from public.contract_policy_versions_v1 other join public.contract_policy_decisions_v1 d on d.policy_version_id=other.id and d.decision='APPROVE'where other.kind='COMMISSION'and other.service_id=p.service_id and other.currency=p.currency and other.country_code=p.country_code and other.id is distinct from p.supersedes_policy_version_id and daterange(other.valid_from,other.valid_until,'[)')&&daterange(p.valid_from,p.valid_until,'[)')and not exists(select 1 from public.contract_policy_versions_v1 successor join public.contract_policy_decisions_v1 sd on sd.policy_version_id=successor.id and sd.decision='APPROVE'where successor.supersedes_policy_version_id=other.id and successor.valid_from<=p.valid_from))then raise exception'COMMISSION_POLICY_EFFECTIVE_WINDOW_OVERLAP'using errcode='55000';end if;
 insert into public.contract_policy_decisions_v1(policy_version_id,decision,content_hash,reason,decided_by)values(p.id,case when p_approve then'APPROVE'else'REJECT'end,p.content_hash,btrim(p_reason),actor);
 result:=jsonb_build_object('outcome','CONTRACT_POLICY_VERSION_DECIDED','policy_version_id',p.id,'decision',case when p_approve then'APPROVE'else'REJECT'end,'content_hash',p.content_hash);
 insert into public.audit_events(actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(actor,'USER','contract.policy.decided','contract_policy_version',p.id::text,p_correlation_id,jsonb_build_object('decision',result->>'decision','content_hash',p.content_hash,'reason',btrim(p_reason)),repeat('0',64));
 perform private.finish_admin_command('contract.policy.decide.'||p.id::text,p_idempotency_key,actor,result);return result;
end$$;
revoke all on function public.decide_contract_policy_version_v1(uuid,boolean,text,text,uuid)from public,anon,authenticated,service_role;
grant execute on function public.decide_contract_policy_version_v1(uuid,boolean,text,text,uuid)to authenticated;
-- The canonical Client party comes from the current verified immutable profile.
create function private.current_client_contract_party_v1(p_org uuid)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,private as $$
declare c public.client_compliance_cases%rowtype;p public.client_profile_versions%rowtype;history public.client_identity_verification_history%rowtype;snapshot jsonb;
begin
 select*into c from public.client_compliance_cases where organization_id=p_org and status='VERIFIED';
 if c.id is null or not private.client_identity_allows_new_operations(p_org)then return null;end if;
 select*into p from public.client_profile_versions where compliance_case_id=c.id and version=c.current_profile_version;
 select*into history from public.client_identity_verification_history where compliance_case_id=c.id and profile_version=p.version order by verified_at desc,id desc limit 1;
 if p.organization_snapshot->>'legal_name'is distinct from(select legal_name from public.organizations where id=p_org)or p.organization_snapshot->>'country_code'is distinct from(select country_code from public.organizations where id=p_org)or coalesce(p.organization_snapshot#>>'{identifiers,ICE}','')!~'^[0-9]{15}$'or coalesce(p.profile_data->>'if_number','')!~'^[0-9]{6,20}$'or length(coalesce(p.profile_data->>'rc_number',''))not between 3 and 32 or(select count(*)from public.organization_identifiers where organization_id=p_org and is_active and identifier_type in('ICE','IF','RC'))<>3 then return null;end if;
 if history.id is null or length(btrim(coalesce(p.profile_data#>>'{registered_address,line1}','')))<3 then return null;end if;
 snapshot:=jsonb_build_object('schema_version',1,'organization_id',p_org,'legal_name',p.organization_snapshot->>'legal_name','country_code',p.organization_snapshot->>'country_code','identifiers',jsonb_build_object('ICE',p.organization_snapshot#>>'{identifiers,ICE}','IF',p.profile_data->>'if_number','RC',p.profile_data->>'rc_number'),'registered_address',concat_ws(', ',nullif(p.profile_data#>>'{registered_address,line1}',''),nullif(p.profile_data#>>'{registered_address,line2}',''),nullif(p.profile_data#>>'{registered_address,postal_code}',''),nullif(p.profile_data->>'registered_city',''),nullif(p.profile_data#>>'{registered_address,country_code}','')),'identity_review_id',history.id,'verified_at',history.verified_at,'compliance_case_id',c.id,'profile_version',p.version,'legal_form',p.profile_data->>'legal_form');
 return snapshot||jsonb_build_object('verified_identity_hash',private.canonical_request_hash(snapshot));
end$$;
revoke all on function private.current_client_contract_party_v1(uuid)from public,anon,authenticated,service_role;
create function public.get_selected_quote_contract_context_v1(p_request_id uuid)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,private as $$
declare sr public.service_requests%rowtype;qv public.quote_versions%rowtype;templates jsonb;commissions jsonb;existing jsonb;provider_party jsonb;selected uuid;can_generate boolean:=false;as_of_date date:=(clock_timestamp()at time zone'Africa/Casablanca')::date;
begin
 select*into sr from public.service_requests where id=p_request_id;
 if auth.uid()is null or sr.id is null or not private.has_org_role(sr.client_organization_id,array['CLIENT_OWNER','CLIENT_ADMIN','CLIENT_BUYER','CLIENT_VIEWER'])then raise exception'CONTRACT_REQUEST_SCOPE_DENIED'using errcode='42501';end if;
 select v.*into qv from public.quote_selection_decisions d join public.quotes q on q.id=d.selected_quote_id and q.status='SELECTED'and q.selected_version_id=d.selected_quote_version_id join public.quote_versions v on v.id=d.selected_quote_version_id join public.rfqs rfq on rfq.id=d.rfq_id where rfq.request_id=sr.id and rfq.request_version_id=sr.current_version_id order by d.created_at desc limit 1;selected:=qv.id;
 select jsonb_build_object('contract_id',contract_id,'contract_version_id',contract_version_id)into existing from public.selected_quote_contract_drafts_v1 where quote_version_id=selected;
 select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'code',p.code,'version',p.version,'title_fr',p.title_fr,'title_ar',p.title_ar)),'[]')into templates from public.contract_policy_versions_v1 p where p.kind='TEMPLATE'and private.contract_policy_applicable_v1(p.id,sr.library_id,sr.service_id,qv.currency,as_of_date,(select country_code from public.organizations where id=sr.client_organization_id));
 select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'code',p.code,'version',p.version,'basis_points',(p.data->>'commission_basis_points')::integer)),'[]')into commissions from public.contract_policy_versions_v1 p where p.kind='COMMISSION'and private.contract_policy_applicable_v1(p.id,sr.library_id,sr.service_id,qv.currency,as_of_date,(select country_code from public.organizations where id=sr.client_organization_id));
 if selected is not null and to_regprocedure('private.provider_quote_identity_snapshot_v1(uuid)')is not null then execute'select private.provider_quote_identity_snapshot_v1($1)'into provider_party using selected;end if;
 can_generate:=auth.jwt()->>'aal'='aal2'and private.has_org_role(sr.client_organization_id,array['CLIENT_OWNER','CLIENT_ADMIN'])and selected is not null and jsonb_array_length(templates)>0 and jsonb_array_length(commissions)=1 and private.subscription_financially_clear(sr.client_organization_id)and private.current_client_contract_party_v1(sr.client_organization_id)is not null and provider_party is not null and private.provider_current_identity_is_verified_v1(qv.provider_organization_id)and coalesce((private.provider_service_eligibility_snapshot(qv.provider_organization_id,sr.service_id)->>'eligible')::boolean,false)and provider_party->>'verified_identity_hash'=private.canonical_request_hash(private.provider_current_identity_snapshot_v1(qv.provider_organization_id));
 return jsonb_build_object('request_id',sr.id,'request_row_version',sr.row_version,'selected_quote_version_id',selected,'existing_contract',existing,'templates',templates,'commission_policies',commissions,'can_generate',coalesce(can_generate,false));
end$$;
revoke all on function public.get_selected_quote_contract_context_v1(uuid)from public,anon,authenticated,service_role;
grant execute on function public.get_selected_quote_contract_context_v1(uuid)to authenticated;
create function public.generate_selected_quote_contract_v1(p_request_id uuid,p_quote_version_id uuid,p_expected_request_row_version integer,p_template_version_id uuid,p_commission_policy_version_id uuid,p_reason text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$
declare actor uuid:=auth.uid();sr public.service_requests%rowtype;rv public.service_request_versions%rowtype;qv public.quote_versions%rowtype;q public.quotes%rowtype;rfq public.rfqs%rowtype;selection public.quote_selection_decisions%rowtype;t public.contract_policy_versions_v1%rowtype;commission public.contract_policy_versions_v1%rowtype;manifest public.selected_quote_contract_drafts_v1%rowtype;request_snapshot jsonb;quote_snapshot jsonb;client_party jsonb;provider_party jsonb;commission_snapshot jsonb;clauses_value jsonb;lines jsonb;options_value jsonb;h text;source_hash text;cached jsonb;result jsonb;contract_id_value uuid;version_id_value uuid;item jsonb;item_index integer:=0;as_of_date date:=(clock_timestamp()at time zone'Africa/Casablanca')::date;eligible_commissions integer;org_lock uuid;
begin
 select*into sr from public.service_requests where id=p_request_id;
 if actor is null or auth.jwt()->>'aal'is distinct from'aal2'or sr.id is null or not private.has_org_role(sr.client_organization_id,array['CLIENT_OWNER','CLIENT_ADMIN'],actor)then raise exception'CONTRACT_GENERATE_DENIED'using errcode='42501';end if;
 if p_quote_version_id is null or p_expected_request_row_version is null or p_expected_request_row_version<1 or p_template_version_id is null or p_commission_policy_version_id is null or length(btrim(coalesce(p_reason,'')))not between 10 and 1000 or p_correlation_id is null then raise exception'INVALID_CANONICAL_CONTRACT_REQUEST'using errcode='22023';end if;
 h:=private.canonical_request_hash(jsonb_build_object('request_id',sr.id,'quote_version_id',p_quote_version_id,'expected_request_version',p_expected_request_row_version,'template_version_id',p_template_version_id,'commission_policy_version_id',p_commission_policy_version_id,'reason',btrim(p_reason)));
 cached:=private.begin_contract_command(sr.client_organization_id,'contract.generate.selected_quote.v1',p_idempotency_key,h,actor);if cached is not null then return cached;end if;
 select*into qv from public.quote_versions where id=p_quote_version_id;
 for org_lock in select distinct id from unnest(array[sr.client_organization_id,qv.provider_organization_id])id where id is not null order by id loop perform pg_advisory_xact_lock(hashtextextended('subscription-financial:'||org_lock::text,0));end loop;
 perform pg_advisory_xact_lock(hashtextextended('service-request:'||sr.id::text,0));select*into sr from public.service_requests where id=p_request_id for update;
 if sr.row_version is distinct from p_expected_request_row_version then raise exception'STALE_CONTRACT_REQUEST'using errcode='40001';end if;
 select*into manifest from public.selected_quote_contract_drafts_v1 where quote_version_id=p_quote_version_id;
 if manifest.quote_version_id is not null then
  if manifest.request_id<>sr.id or manifest.template_policy_version_id<>p_template_version_id or manifest.commission_policy_version_id<>p_commission_policy_version_id then raise exception'CONTRACT_ALREADY_DRAFTED_DIFFERENT_POLICY'using errcode='55000';end if;
  result:=jsonb_build_object('outcome','SELECTED_QUOTE_CONTRACT_DRAFTED','contract_id',manifest.contract_id,'contract_version_id',manifest.contract_version_id,'content_hash',(select content_hash from public.contract_versions where id=manifest.contract_version_id));perform private.finish_contract_command(sr.client_organization_id,'contract.generate.selected_quote.v1',p_idempotency_key,result);return result;
 end if;
 select*into q from public.quotes where id=qv.quote_id for update;select*into rfq from public.rfqs where id=q.rfq_id;select*into selection from public.quote_selection_decisions where rfq_id=rfq.id;
 if qv.id is null or q.status<>'SELECTED'or q.selected_version_id is distinct from qv.id or selection.selected_quote_version_id is distinct from qv.id or selection.selected_quote_id is distinct from q.id or rfq.request_id is distinct from sr.id then raise exception'SELECTED_QUOTE_REQUIRED'using errcode='55000';end if;
 if rfq.request_version_id is distinct from sr.current_version_id then raise exception'REQUEST_QUOTE_VERSION_MISMATCH'using errcode='40001';end if;
 if not exists(select 1 from public.organizations where id=sr.client_organization_id and status='ACTIVE')or not exists(select 1 from public.organizations where id=qv.provider_organization_id and status='ACTIVE')then raise exception'VERIFIED_LEGAL_PARTIES_REQUIRED'using errcode='55000';end if;
 if not private.subscription_financially_clear(sr.client_organization_id)then raise exception'CLIENT_FINANCIAL_HOLD_ACTIVE'using errcode='55000';end if;
 if not coalesce((private.provider_service_eligibility_snapshot(qv.provider_organization_id,sr.service_id)->>'eligible')::boolean,false)then raise exception'PROVIDER_NOT_ELIGIBLE_FOR_NEW_COMMITMENT'using errcode='55000';end if;
 client_party:=private.current_client_contract_party_v1(sr.client_organization_id);
 if to_regprocedure('private.provider_quote_identity_snapshot_v1(uuid)')is not null then execute'select private.provider_quote_identity_snapshot_v1($1)'into provider_party using qv.id;end if;
 if client_party is null or provider_party is null or not private.provider_current_identity_is_verified_v1(qv.provider_organization_id)or provider_party->>'verified_identity_hash'is distinct from private.canonical_request_hash(private.provider_current_identity_snapshot_v1(qv.provider_organization_id))then raise exception'VERIFIED_LEGAL_PARTIES_REQUIRED'using errcode='55000';end if;
 if length(btrim(coalesce(provider_party->>'registered_address','')))<3 or coalesce(provider_party#>>'{identifiers,ICE}','')!~'^[0-9]{15}$'or coalesce(client_party#>>'{identifiers,ICE}','')!~'^[0-9]{15}$'then raise exception'VERIFIED_LEGAL_PARTIES_REQUIRED'using errcode='55000';end if;
 perform pg_advisory_xact_lock(hashtextextended('contract-commission:'||sr.service_id::text||':'||qv.currency,0));
 select*into t from public.contract_policy_versions_v1 where id=p_template_version_id and kind='TEMPLATE';select*into commission from public.contract_policy_versions_v1 where id=p_commission_policy_version_id and kind='COMMISSION';
 if t.id is null or not private.contract_policy_applicable_v1(t.id,sr.library_id,sr.service_id,qv.currency,as_of_date,(select country_code from public.organizations where id=sr.client_organization_id))then raise exception'CONTRACT_TEMPLATE_REQUIRED'using errcode='55000';end if;
 if t.country_code is distinct from client_party->>'country_code'or t.country_code is distinct from provider_party->>'country_code'then raise exception'CONTRACT_PARTY_JURISDICTION_MISMATCH'using errcode='55000';end if;
 select count(*)into eligible_commissions from public.contract_policy_versions_v1 p where p.kind='COMMISSION'and private.contract_policy_applicable_v1(p.id,sr.library_id,sr.service_id,qv.currency,as_of_date,(select country_code from public.organizations where id=sr.client_organization_id));
 if commission.id is null or eligible_commissions<>1 or not private.contract_policy_applicable_v1(commission.id,sr.library_id,sr.service_id,qv.currency,as_of_date,(select country_code from public.organizations where id=sr.client_organization_id))then raise exception'COMMISSION_POLICY_REQUIRED'using errcode='55000';end if;
 select*into rv from public.service_request_versions where id=rfq.request_version_id and request_id=sr.id;
 if rv.id is null then raise exception'REQUEST_VERSION_NOT_FOUND'using errcode='55000';end if;
 select coalesce(jsonb_agg(to_jsonb(i)||jsonb_build_object('quantity',i.quantity::text,'unit_price_minor',i.unit_price_minor::text,'subtotal_minor',i.subtotal_minor::text,'tax_minor',i.tax_minor::text,'total_minor',i.total_minor::text)order by i.line_number),'[]')into lines from public.quote_items i where i.quote_version_id=qv.id;
 select coalesce(jsonb_agg(to_jsonb(o)||jsonb_build_object('amount_minor',o.amount_minor::text)order by o.option_key),'[]')into options_value from public.quote_options o where o.quote_version_id=qv.id;
 if jsonb_array_length(lines)=0 or(select coalesce(sum(subtotal_minor),0)from public.quote_items where quote_version_id=qv.id)is distinct from qv.subtotal_minor::numeric or(select coalesce(sum(tax_minor),0)from public.quote_items where quote_version_id=qv.id)is distinct from qv.tax_minor::numeric then raise exception'QUOTE_PRICE_SOURCE_MISMATCH'using errcode='23514';end if;
 request_snapshot:=to_jsonb(rv)||jsonb_build_object('request_id',sr.id,'request_version_id',rv.id,'selection_decision',to_jsonb(selection));
 quote_snapshot:=to_jsonb(qv)||jsonb_build_object('quote_version_id',qv.id,'subtotal_minor',qv.subtotal_minor::text,'tax_minor',qv.tax_minor::text,'total_minor',qv.total_minor::text,'recurring_subtotal_minor',qv.recurring_subtotal_minor::text,'items',lines,'options',options_value);
 commission_snapshot:=commission.data||jsonb_build_object('policy_version_id',commission.id,'policy_code',commission.code,'policy_version',commission.version,'content_hash',commission.content_hash,'approval_reference',commission.approval_reference);
 clauses_value:=t.data->'clauses'||jsonb_build_object('template_policy_version_id',t.id,'template_code',t.code,'template_version',t.version,'template_content_hash',t.content_hash,'approval_reference',t.approval_reference);
 source_hash:=private.canonical_request_hash(jsonb_build_object('request',request_snapshot,'quote',quote_snapshot,'clauses',clauses_value,'commission',commission_snapshot,'client_party',client_party,'provider_party',provider_party,'price_minor',qv.total_minor::text,'currency',qv.currency));
 insert into public.contracts(client_organization_id,provider_organization_id,created_by)values(sr.client_organization_id,qv.provider_organization_id,actor)returning id into contract_id_value;
 insert into public.contract_versions(contract_id,version,selected_quote_version_id,request_snapshot,quote_snapshot,clauses,price_minor,currency,commission_rule_snapshot,content_hash,change_reason,created_by)values(contract_id_value,1,qv.id,request_snapshot,quote_snapshot,clauses_value,qv.total_minor,qv.currency,commission_snapshot,source_hash,btrim(p_reason),actor)returning id into version_id_value;
 insert into public.contract_parties(contract_version_id,organization_id,party_role,legal_snapshot)values(version_id_value,sr.client_organization_id,'CLIENT',client_party),(version_id_value,qv.provider_organization_id,'PROVIDER',provider_party);
 for item in select*from jsonb_array_elements(qv.deliverables)loop
  item_index:=item_index+1;insert into public.contract_items(contract_version_id,item_key,item_type,label_fr,label_ar,details,sort_order)values(version_id_value,'DELIVERABLE_'||item_index,'DELIVERABLE','Livrable '||item_index,'تسليم '||item_index,jsonb_build_object('source_quote_version_id',qv.id,'source_deliverable',item),item_index);
 end loop;
 insert into public.selected_quote_contract_drafts_v1(quote_version_id,request_id,request_version_id,selection_decision_rfq_id,contract_id,contract_version_id,template_policy_version_id,commission_policy_version_id,source_hash,created_by)values(qv.id,sr.id,rv.id,selection.rfq_id,contract_id_value,version_id_value,t.id,commission.id,source_hash,actor);
 result:=jsonb_build_object('outcome','SELECTED_QUOTE_CONTRACT_DRAFTED','contract_id',contract_id_value,'contract_version_id',version_id_value,'content_hash',source_hash);
 insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(sr.client_organization_id,actor,'USER','contract.selected_quote.drafted','contract',contract_id_value::text,p_correlation_id,jsonb_build_object('contract_version_id',version_id_value,'request_id',sr.id,'quote_version_id',qv.id,'source_hash',source_hash,'template_policy_version_id',t.id,'commission_policy_version_id',commission.id,'reason',btrim(p_reason)),repeat('0',64));
 insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(sr.client_organization_id,'contract',contract_id_value::text,'ContractGeneratedV1',p_correlation_id,result||jsonb_build_object('request_id',sr.id,'quote_version_id',qv.id,'provider_organization_id',qv.provider_organization_id,'status','DRAFT'),p_idempotency_key);
 perform private.finish_contract_command(sr.client_organization_id,'contract.generate.selected_quote.v1',p_idempotency_key,result);return result;
end$$;
revoke all on function public.generate_selected_quote_contract_v1(uuid,uuid,integer,uuid,uuid,text,text,uuid)from public,anon,authenticated,service_role;
grant execute on function public.generate_selected_quote_contract_v1(uuid,uuid,integer,uuid,uuid,text,text,uuid)to authenticated;
-- Preserve the legacy ABI for explicit refusals; arbitrary JSON is never a
-- second route to a new contract. Existing immutable contracts are untouched.
create or replace function public.generate_contract(p_client_organization_id uuid,p_provider_organization_id uuid,p_request_snapshot jsonb,p_quote_snapshot jsonb,p_clauses jsonb,p_price_minor bigint,p_currency text,p_commission_rule_snapshot jsonb,p_client_legal_snapshot jsonb,p_provider_legal_snapshot jsonb,p_change_reason text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$
begin
 if auth.uid()is null or not private.has_org_role(p_client_organization_id,array['CLIENT_OWNER','CLIENT_ADMIN'])then raise exception'CONTRACT_GENERATE_DENIED'using errcode='42501';end if;
 if p_price_minor is null or p_price_minor<0 or coalesce(p_currency,'')!~'^[A-Z]{3}$'then raise exception'INVALID_CONTRACT'using errcode='22023';end if;
 raise exception'CANONICAL_SELECTED_QUOTE_CONTRACT_REQUIRED'using errcode='55000';
end$$;
revoke all on function public.generate_contract(uuid,uuid,jsonb,jsonb,jsonb,bigint,text,jsonb,jsonb,jsonb,text,text,uuid)from public,anon,service_role;
grant execute on function public.generate_contract(uuid,uuid,jsonb,jsonb,jsonb,bigint,text,jsonb,jsonb,jsonb,text,text,uuid)to authenticated;
create function private.lock_contract_financial_parties_v1(p_client uuid,p_provider uuid)returns void language plpgsql security definer set search_path=pg_catalog as $$
declare org uuid;begin for org in select distinct id from unnest(array[p_client,p_provider])id where id is not null order by id loop perform pg_advisory_xact_lock(hashtextextended('subscription-financial:'||org::text,0));end loop;end$$;
revoke all on function private.lock_contract_financial_parties_v1(uuid,uuid)from public,anon,authenticated,service_role;
-- An amendment cannot choose a platform commission through a free JSON body.
-- Only party writers may propose one; read-only access is never write authority.
do $$declare definition text;target text;begin
 select pg_get_functiondef('public.create_contract_amendment(uuid,text,jsonb,bigint,integer,jsonb,jsonb,text,uuid)'::regprocedure)into definition;
 target:='select id into v from public.contract_versions where contract_id=c.id and version=c.current_version;';
 if strpos(definition,target)=0 then raise exception'AMENDMENT_CANONICAL_POLICY_PATCH_TARGET_MISSING';end if;
 definition:=replace(definition,target,'perform private.lock_contract_financial_parties_v1(c.client_organization_id,c.provider_organization_id);select*into c from public.contracts where id=p_contract_id for update;if c.status not in(''ACTIVE'',''AMENDED'')then raise exception''AMENDMENT_CREATE_DENIED''using errcode=''42501'';end if;'||target||'if auth.jwt()->>''aal''is distinct from''aal2''or not(private.has_org_role(c.client_organization_id,array[''CLIENT_OWNER'',''CLIENT_ADMIN''],a)or private.has_org_role(c.provider_organization_id,array[''PROVIDER_OWNER'',''PROVIDER_MANAGER''],a))then raise exception''AMENDMENT_CREATE_DENIED''using errcode=''42501'';end if;
 if p_commission_rule_snapshot is distinct from(select commission_rule_snapshot from public.contract_versions where id=v)then raise exception''COMMISSION_CHANGE_REQUIRES_APPROVED_CONTRACT_POLICY''using errcode=''55000'';end if;
 if not private.subscription_financially_clear(c.client_organization_id)or private.current_client_contract_party_v1(c.client_organization_id)is null or not private.provider_current_identity_is_verified_v1(c.provider_organization_id)or private.provider_has_overdue_matricia_invoice(c.provider_organization_id)then raise exception''CONTRACT_NEW_COMMITMENT_NOT_ALLOWED''using errcode=''55000'';end if;');execute definition;
end$$;
notify pgrst,'reload schema';
commit;
